#!/bin/bash
# Load the five legal texts (docs/legal, decision 36) into legal_policies as version 1.0.
# APPLY=0 is the rehearsal: it only prints what would change. APPLY=1 writes.
# Missing key -> insert 1.0. Existing key -> new major version, old text kept in change_log, audit row written.
# Prints keys, versions and lengths only; never a text or a secret.
set +e
APPLY=1
DK="sudo -n docker"
echo "## legal-policies (APPLY=$APPLY)"
echo '' | base64 -d | timeout 60 $DK exec -i -e APPLY=$APPLY nabdah-backend node -e '
  const mongoose = require("mongoose");
  let raw = ""; process.stdin.on("data", (d) => raw += d);
  process.stdin.on("end", async () => {
    const docs = JSON.parse(raw);
    const uri = process.env.MONGO_URL || process.env.MONGODB_URI || process.env.MONGO_URI || process.env.DATABASE_URL;
    if (!uri) { console.log("no mongo uri env"); return; }
    const apply = process.env.APPLY === "1";
    const c = await mongoose.createConnection(uri, { serverSelectionTimeoutMS: 15000, dbName: process.env.DB_NAME || undefined }).asPromise();
    const P = c.db.collection("legal_policies");
    console.log("db:", c.db.databaseName, "| policies before:", await P.countDocuments({}));
    for (const d of docs) {
      const ex = await P.findOne({ key: d.key });
      const now = new Date();
      if (!ex) {
        console.log(d.key, "-> insert 1.0, chars", d.content_ar.length);
        if (apply) await P.insertOne({ ...d, content_en: "", version: "1.0", effective_date: now, last_updated: now,
          change_log: [{ version: "1.0", date: now, note: "decision 36: published draft, lawyer review pending", by: "server-ops" }] });
        continue;
      }
      if (ex.content_ar === d.content_ar) { console.log(d.key, "-> unchanged", ex.version); continue; }
      const maj = parseInt(String(ex.version || "0").split(".")[0], 10) || 0;
      const v = (maj + 1) + ".0";
      console.log(d.key, "-> exists", ex.version, "chars", (ex.content_ar || "").length, "=> update to", v, "chars", d.content_ar.length);
      if (apply) {
        await P.updateOne({ key: d.key }, { $set: { title_ar: d.title_ar, title_en: d.title_en, applies_to: d.applies_to,
          requires_acceptance: d.requires_acceptance, content_ar: d.content_ar, version: v, effective_date: now, last_updated: now },
          $push: { change_log: { version: v, date: now, note: "decision 36: published draft, lawyer review pending", by: "server-ops",
            previous_content_ar: ex.content_ar || "" } } });
        await c.db.collection("admin_audit_log").insertOne({ action: "legal.policy.edit", target: "legal_policies:" + d.key,
          admin_id: "server-ops", before: { version: ex.version }, after: { version: v }, ip: null, device: null, timestamp: now });
      }
    }
    const after = await P.find({}, { projection: { _id: 0, key: 1, version: 1 } }).sort({ key: 1 }).toArray();
    console.log("policies after:", after.map((p) => p.key + "@" + p.version).join(" "));
    await c.close();
  });
' 2>&1 | sed -E 's#mongodb(\+srv)?://[^ ]+#mongodb://***#g' | head -30
echo "-- public read check"
for k in patient_terms privacy_policy provider_agreement telehealth_consent refund_policy; do
  echo "$k -> $(curl -sk --max-time 8 -H 'Host: api.nabd.plus' "https://127.0.0.1/api/v1/legal/policy/$k?lang=ar" | python3 -c 'import sys,json
try:
  d=json.load(sys.stdin); print((d or {}).get("version"), len((d or {}).get("content") or ""))
except Exception as e: print("no json")')"
done
echo "## legal-policies done"

